package com.bank.spark.engine;

import com.bank.spark.model.Txn;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Predicate;
import java.util.function.UnaryOperator;
import java.util.logging.Logger;

// Simulates Spark's model: partitioning, lazy DAG, parallel execution, lineage recompute.
public class MiniSpark {
    private static final Logger log = Logger.getLogger(MiniSpark.class.getName());

    private final List<Partition> partitions = new ArrayList<>();
    // Lineage: the chain of lazy transformations (nothing runs until an action).
    private final List<UnaryOperator<List<Txn>>> lineage = new ArrayList<>();

    public MiniSpark parallelize(List<Txn> data, int numPartitions) {
        int size = (int) Math.ceil((double) data.size() / numPartitions);
        for (int i = 0; i < numPartitions; i++) {
            int from = i * size, to = Math.min(from + size, data.size());
            if (from < to) partitions.add(new Partition(i, new ArrayList<>(data.subList(from, to))));
        }
        log.info("parallelize: created " + partitions.size() + " partitions (lazy)");
        return this;
    }

    // Lazy transformation — only records intent in the lineage.
    public MiniSpark filter(Predicate<Txn> p) {
        lineage.add(list -> { List<Txn> out = new ArrayList<>();
            for (Txn t : list) if (p.test(t)) out.add(t); return out; });
        log.fine("filter added to lineage (not executed yet)");
        return this;
    }

    // ACTION — triggers execution of the whole DAG, in parallel per partition.
    public Map<String, BigDecimal> sumByAccount() throws Exception {
        log.info("ACTION sumByAccount: executing DAG across partitions in parallel");
        ExecutorService pool = Executors.newFixedThreadPool(partitions.size());
        try {
            List<Future<Map<String, BigDecimal>>> futures = new ArrayList<>();
            for (Partition part : partitions) {
                futures.add(pool.submit(() -> runPartition(part)));
            }
            Map<String, BigDecimal> total = new LinkedHashMap<>();
            for (Future<Map<String, BigDecimal>> f : futures) {
                f.get().forEach((k, v) -> total.merge(k, v, BigDecimal::add));
            }
            return total;
        } finally {
            pool.shutdown();
        }
    }

    // One executor task: apply lineage to a partition, then aggregate locally.
    private Map<String, BigDecimal> runPartition(Partition part) {
        List<Txn> data = part.getData();
        for (UnaryOperator<List<Txn>> step : lineage) data = step.apply(data);
        log.fine(() -> "partition " + part.getId() + " processed " + part.getData().size() + " rows");
        Map<String, BigDecimal> local = new LinkedHashMap<>();
        for (Txn t : data) local.merge(t.getAccountId(), t.getAmount(), BigDecimal::add);
        return local;
    }
}
