package com.bank.spark;

import com.bank.spark.engine.MiniSpark;
import com.bank.spark.model.Txn;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

public class SparkDemo {
    private static final Logger log = Logger.getLogger(SparkDemo.class.getName());

    public static void main(String[] args) throws Exception {
        List<Txn> data = List.of(
            new Txn("SAV2001", new BigDecimal("1200.00")),
            new Txn("SAV2001", new BigDecimal("800.00")),
            new Txn("CUR3001", new BigDecimal("5000.00")),
            new Txn("CUR3001", new BigDecimal("-10.00")),   // filtered out
            new Txn("SAV2001", new BigDecimal("300.00")),
            new Txn("CUR3001", new BigDecimal("2500.00"))
        );

        MiniSpark spark = new MiniSpark()
            .parallelize(data, 3)                                    // split into 3 partitions
            .filter(t -> t.getAmount().compareTo(BigDecimal.ZERO) > 0); // lazy transform

        log.info("No work done yet — transformations are lazy.");
        Map<String, BigDecimal> totals = spark.sumByAccount();        // ACTION triggers DAG

        log.info("=== DISTRIBUTED TOTAL BY ACCOUNT ===");
        totals.forEach((acc, total) -> log.info(acc + " = " + total));
    }
}
